1	// grow_with_claudinite task: conversation-extract — the conversation-side sibling
2	// of growth-extract (per-project-scheduling DESIGN §6). Mines the repo's captured
3	// conversation logs (the orphan `conversation-logs` branch) for durable lessons,
4	// posts a short summary of the exchange behind each extracted rule on its issue,
5	// and prunes logs past the entry's retention. Worker: task.md.
6	//
7	// Self-contained (imports nothing): the whole contract is this default export.
8	
9	export default {
10	  id: 'conversation-extract',
11	  frequency: 'daily-1h',           // the 03:00 slot, alongside growth-extract (DESIGN §2)
12	  precondition_signals: ['commits', 'conversationLogs'],
13	  agent_model: 'opus',                   // deciding what clears the lesson bar is the heaviest judgment, and its PR auto-merges without a human gate
14	  expected_outcome: 'merged-pr',            // lessons ride an auto-merging PR; the retention prune is a push to the non-default logs branch (outside the taxonomy)
15	  agent_instructions: 'task.md',
16	  agent_execution_timeout: 1800,            // mining logs + a retention prune — generous bound, extreme protection
17	
18	  // Two independent reasons to run, so the age-based prune fires on quiet repos
19	  // too (the old weekly-full crutch retires — a log ages out on wall time, not on
20	  // the repo changing, DESIGN §6):
21	  //   (a) a substantive merge — a fresh capture now sits on the logs branch;
22	  //   (b) a log on the branch is ACTUALLY past retention — there is aged material
23	  //       to give a final hindsight pass and prune, regardless of activity.
24	  //
25	  // (b) tests the age, not just "a branch exists and retention is configured":
26	  // that pair is true on every capturing repo every day, which dispatched an opus
27	  // agent daily to find nothing prunable. The prune's trigger is the same fact the
28	  // prune acts on — the oldest log being older than retention.
29	  precondition(signals) {
30	    const substantive = signals.commits?.substantiveChange === true;
31	    const logs = signals.conversationLogs ?? {};
32	    const retention = logs.retentionDays;
33	    const oldest = logs.oldestLogAgeDays;
34	    const configured = logs.present === true && typeof retention === 'number';
35	    const aged = configured && typeof oldest === 'number' && oldest > retention;
36	
37	    if (substantive) {
38	      return { run: true, reason: 'substantive merge — extract any freshly captured conversation logs (+ retention prune)' };
39	    }
40	    if (aged) {
41	      return { run: true, reason: `oldest log ${oldest.toFixed(1)}d old vs retention ${retention}d — run the age-based retention prune` };
42	    }
43	    if (configured) {
44	      return { run: false, reason: `no substantive merge and no log older than retention ${retention}d — nothing to prune` };
45	    }
46	    return { run: false, reason: logs.present ? 'no substantive merge and retention unset — nothing to prune' : 'no fresh captures and no logs branch' };
47	  },
48	};
