1	// grow_with_claudinite task: growth-extract — the growth lifecycle's CAPTURE
2	// stage (per-project-scheduling DESIGN §6). Reviews the repo's recent activity and
3	// folds any durable, reusable lesson into the repo's own local packs, landing
4	// through a PR that auto-merges once the repo's checks pass. Worker: task.md.
5	//
6	// Self-contained (imports nothing): the whole contract is this default export.
7	
8	export default {
9	  id: 'growth-extract',
10	  frequency: 'daily-1h',           // the 03:00 slot — lessons captured from an already-converged mount (DESIGN §2)
11	  precondition_signals: ['commits', 'prs', 'issues'],
12	  agent_model: 'opus',                   // generalizing/curating lessons is the heaviest judgment, and auto-merge means no human reviews the PR
13	  expected_outcome: 'merged-pr',            // additive edits to the repo's own local packs; arms auto-merge after CI
14	  agent_instructions: 'task.md',
15	  agent_execution_timeout: 1800,            // curating a lesson over the window — generous bound, extreme protection
16	
17	  // Fire on a SUBSTANTIVE default-branch change (not any change): a bot bump /
18	  // [skip ci] / nightly-baselining commit advancing main is not a lesson to
19	  // extract — `commits.substantiveChange` already applies that classification.
20	  // Pass the substantive shas + touched PR/issue numbers as binding scope so the
21	  // worker reads exactly the window that triggered it — INCLUDING the PRs merged
22	  // during it. Context is binding scope and task.md forbids widening past it, so a
23	  // merged PR the precondition does not name is unreadable to the worker; merged
24	  // PRs carry the review discussion behind a change, usually the window's richest
25	  // lesson source. This does not change WHEN the task fires — the gate is still a
26	  // substantive default-branch change — only what the run is allowed to read.
27	  precondition(signals) {
28	    const commits = signals.commits ?? {};
29	    if (!commits.substantiveChange) {
30	      return { run: false, reason: 'no substantive default-branch change in the window' };
31	    }
32	    const shas = (commits.list ?? []).filter((c) => c.substantive).map((c) => c.sha.slice(0, 7));
33	    const prs = signals.prs?.touched ?? [];
34	    const merged = (signals.prs?.merged ?? []).map((p) => p.number);
35	    const issues = signals.issues?.touched ?? [];
36	    const context = [`Scope: the ${shas.length} substantive commit(s) in the window — ${shas.join(', ')}.`];
37	    if (merged.length) context.push(`PRs merged in the window — read each one's diff and its review discussion: ${merged.map((n) => `#${n}`).join(', ')}.`);
38	    if (prs.length) context.push(`PRs touched in the window: ${prs.map((n) => `#${n}`).join(', ')}.`);
39	    if (issues.length) context.push(`Issues touched in the window: ${issues.map((n) => `#${n}`).join(', ')}.`);
40	    return { run: true, reason: `${shas.length} substantive commit(s) in the window`, context };
41	  },
42	};
43

