// grow_with_claudinite task: growth-extract — the growth lifecycle's CAPTURE
// stage (per-project-scheduling DESIGN §6). Reviews the repo's recent activity and
// folds any durable, reusable lesson into the repo's own local packs, landing
// through a PR that auto-merges once the repo's checks pass. Worker: task.md.
//
// Self-contained (imports nothing): the whole contract is this default export.

export default {
  id: 'growth-extract',
  frequency: 'daily-1h',           // the 03:00 slot — lessons captured from an already-converged mount (DESIGN §2)
  precondition_signals: ['commits', 'prs', 'issues'],
  agent_model: 'opus',                   // generalizing/curating lessons is the heaviest judgment, and auto-merge means no human reviews the PR
  expected_outcome: 'merged-pr',            // additive edits to the repo's own local packs; arms auto-merge after CI
  agent_instructions: 'task.md',
  agent_execution_timeout: 1800,            // curating a lesson over the window — generous bound, extreme protection

  // Fire on a SUBSTANTIVE default-branch change (not any change): a bot bump /
  // [skip ci] / nightly-baselining commit advancing main is not a lesson to
  // extract — `commits.substantiveChange` already applies that classification.
  // Pass the substantive shas + touched PR/issue numbers as binding scope so the
  // worker reads exactly the window that triggered it — INCLUDING the PRs merged
  // during it. Context is binding scope and task.md forbids widening past it, so a
  // merged PR the precondition does not name is unreadable to the worker; merged
  // PRs carry the review discussion behind a change, usually the window's richest
  // lesson source. This does not change WHEN the task fires — the gate is still a
  // substantive default-branch change — only what the run is allowed to read.
  precondition(signals) {
    const commits = signals.commits ?? {};
    if (!commits.substantiveChange) {
      return { run: false, reason: 'no substantive default-branch change in the window' };
    }
    const shas = (commits.list ?? []).filter((c) => c.substantive).map((c) => c.sha.slice(0, 7));
    const prs = signals.prs?.touched ?? [];
    const merged = (signals.prs?.merged ?? []).map((p) => p.number);
    const issues = signals.issues?.touched ?? [];
    const context = [`Scope: the ${shas.length} substantive commit(s) in the window — ${shas.join(', ')}.`];
    if (merged.length) context.push(`PRs merged in the window — read each one's diff and its review discussion: ${merged.map((n) => `#${n}`).join(', ')}.`);
    if (prs.length) context.push(`PRs touched in the window: ${prs.map((n) => `#${n}`).join(', ')}.`);
    if (issues.length) context.push(`Issues touched in the window: ${issues.map((n) => `#${n}`).join(', ')}.`);
    return { run: true, reason: `${shas.length} substantive commit(s) in the window`, context };
  },
};

// grow_with_claudinite task: prose-to-checks-sweep — mine a repo's EXISTING pack
// prose for always-testable rules the conversion missed and convert the strongest
// ones (per-project-scheduling redesign). A per-repo task: every repo declaring the
// growth pack sweeps its OWN packs. Which pack paths it works is a config setting,
// `pack_paths`, defaulting to the repo's own local packs; Claudinite itself sets it
// to ALSO include its core `packs/` (projects are not expected to improve core canon
// packs — only Claudinite does). The method is owned by the prose-to-checks skill.
//
// Self-contained (imports nothing): the whole contract is this default export.

// The repo's own capture surface — a consumer improves only its LOCAL packs.
const DEFAULT_PACK_PATHS = ['.claudinite/local/packs'];

export default {
  id: 'prose-to-checks-sweep',
  frequency: 'daily',                    // works the standing backlog a slice at a time
  precondition_signals: [],              // the backlog is standing prose, not a windowed signal
  agent_model: 'opus',                   // judging convertibility and authoring checks + fixtures is heavy judgment
  expected_outcome: 'open-pr',           // converts prose to checks in an owner-approved PR (a check can break CI, so it's reviewed)
  agent_instructions: 'task.md',
  agent_execution_timeout: 2700,         // reading the packs + authoring a check with fixtures — generous bound

  // Fires daily. The pack paths to sweep come from this pack entry's `pack_paths`
  // config (default: the repo's own local packs); the canon overrides it to add its
  // core `packs/`. The worker works whatever convertible prose remains under those
  // paths and no-ops cheaply when the backlog is dry.
  precondition(_signals, config) {
    const paths = Array.isArray(config?.pack_paths) && config.pack_paths.length ? config.pack_paths : DEFAULT_PACK_PATHS;
    return {
      run: true,
      reason: `daily prose-to-checks backlog sweep over ${paths.join(', ')} (no-ops cheaply when dry)`,
      context: [`Pack paths to sweep (work ONLY these; never a read-only mounted canon pack under .claudinite/shared/): ${paths.join(', ')}.`],
    };
  },
};

// product-wiki task: wiki-growth — one research-and-refine pass over the repo's
// product wikis (per-project-scheduling DESIGN §6). Worker: task.md.
//
// WEEKLY, not daily and not commit-gated: research arrives on the world's clock,
// not the repo's, and a nightly high-model pass economically pressures
// fabrication (the Karpathy LLM-wiki cadence). The `commits` signal is declared
// only so the precondition can note recent product-relevant movement in context;
// the run itself is scheduled by frequency, not triggered by a commit.
//
// The open-growth-PR preflight stays in task.md, and is NOT subsumed by the
// scheduler: planDispatch guards at most one open dispatch ISSUE per (pack,
// task) — it never looks at pull requests. A completed run converges and closes
// its own dispatch issue while leaving the growth PR open for review, so the
// next weekly slot finds no open issue in the family and dispatches freely. The
// preflight is the only thing standing between an unreviewed PR and a second
// round of research stacked on top of it; do not delete it on the strength of
// the issue guard.
//
// The precondition itself deliberately never declines: a wiki grows on research
// availability, not repo activity, so there is no cheaper gate to apply than the
// weekly slot, and the worker's own stop condition (no citable material → no
// branch, no PR) is the real "nothing to do" outcome.
//
// Self-contained (imports nothing): the whole contract is this default export.

export default {
  id: 'wiki-growth',
  frequency: 'weekly',             // fires at the weekly anchor (DESIGN §2) — the world's clock, not the repo's
  precondition_signals: ['commits'],
  agent_model: 'opus',                   // open-web research + curation is the heaviest judgment, and the PR review gate is the last catch for fabrication
  expected_outcome: 'open-pr',              // web-researched claims entering a knowledge base need the human review gate — never merged, never pushed to default
  agent_instructions: 'task.md',
  agent_execution_timeout: 2700,            // open-web research is the least predictable of the tasks — very generous

  // The weekly slot IS the trigger — there is no cheaper gate to apply, because a
  // wiki grows on research availability, not repo activity. Always run when due;
  // the worker's own stop condition (no citable material → no branch, no PR) is
  // the real "nothing to do" outcome, and task.md's open-growth-PR preflight —
  // not the scheduler, which guards issues only — prevents stacking a second
  // round on an unreviewed PR.
  precondition(signals) {
    const touched = signals.commits?.touchedPaths ?? [];
    const wikiMoved = touched.some((p) => p.startsWith('product-wiki/'));
    const context = wikiMoved
      ? ['The product-wiki tree moved in the window — spot-check any pages whose cited claims the change may have superseded.']
      : [];
    return { run: true, reason: 'weekly product-wiki growth pass', context };
  },
};

// sheepdog task: fleet-census — the coverage/adoption audit, as a scheduled task.
// `agent_model: 'none'` with `agent_preprocessing: 'node worker.mjs'`: the whole
// pass is deterministic code the scheduler runs as a subprocess — no agent, no
// dispatch issue. The worker calls its sibling, the census (check-fleet-coverage.mjs):
// enumerate every repo under the configured owner, classify each (covered /
// uncovered / excluded / skipped), and converge one adoption ISSUE per uncovered
// repo in this (sheepdog) repo.
//
// It used to be a `workflow_dispatch`-only Action of its own, materialized into
// the sheepdog repo, existing only to hold FLEET_GITHUB_TOKEN. That workflow is
// gone: preprocessing runs Action-side inside the scheduler workflow, so repo
// Actions secrets are reachable there, and `required_secrets` stamps the name into
// the scheduler workflow's env (basics/scheduled-tasks.md — "a workflow that
// exists only to hold a secret is redundant"). Its `report-failure` job is gone
// too: a non-zero preprocessing exit now converges to a `needs-human` issue via
// the scheduler (and a scheduler-run failure to `workflow-failure`), which is the
// same escalation with one fewer file.
//
// CLASSIFICATION (per-project-scheduling DESIGN §6, the same note RULES.md
// carries): this is an ORDINARY PACK TASK, not a fleet mechanism. Its
// *implementation* happens to scan every repo under the owner, but its
// declaration, scheduling and lifecycle are exactly those of any pack task — it is
// active because this repo declares the sheepdog pack, and it runs however this
// repo's tasks run. Hence no `session_scope: 'fleet'` and no `fleet` signal: those
// describe how a task is WIRED, and nothing about this task's wiring is fleet-shaped.
// The cross-repo reach lives in the implementation, never in the declaration.
//
// Self-contained (imports nothing): the whole contract is this default export.

export default {
  id: 'fleet-census',
  frequency: 'daily',                    // a daily coverage audit — the 04:00 slot
  precondition_signals: [],              // no signal — the worker reads the fleet itself, over the PAT
  agent_model: 'none',                   // pure code — no agent (agent-preprocessing DESIGN §4)
  expected_outcome: 'none',              // the honest ceiling: the census opens ADOPTION ISSUES, never a PR
  agent_instructions: 'task.md',         // vestigial for a none task; the real work is the preprocessing command
  agent_preprocessing: 'node worker.mjs',
  // The census walks EVERY repo in the fleet: one paged enumeration plus one
  // marker-check REST call per repo, all serial, then the adoption-issue
  // convergence. A few hundred repos is minutes, not seconds — and a secondary
  // rate limit makes it slower still. 15 minutes is ~10x the expected walk while
  // staying well inside the hourly scheduler cadence, so a hung census is killed
  // long before the next run could collide with it.
  agent_preprocessing_timeout: 900,
  required_secrets: ['FLEET_GITHUB_TOKEN'], // the account-spanning PAT the census reads the fleet with

  // Fire daily unconditionally: the census is cheap to no-op (a converged fleet
  // opens and closes nothing) and there is no collectable signal that would tell
  // us in advance whether coverage changed — a repo created, deleted, archived or
  // adopted under the owner is invisible to every per-repo collector. The whole
  // question the task answers lives outside this repo, so the answer is the run.
  precondition() {
    return { run: true, reason: 'daily fleet coverage audit (the census converges adoption issues and no-ops cheaply on a covered fleet)' };
  },
};

// sheepdog task: fleet-freshness — is each COVERED member actually keeping up?
// `agent_model: 'none'` with `agent_preprocessing: 'node worker.mjs'`: the whole
// pass is deterministic code the scheduler runs as a subprocess — no agent, no
// dispatch issue. The worker calls its sibling, the sweep (check-fleet-freshness.mjs):
// probe every covered repo under the configured owner, classify its drift by root
// cause (no-stamp / no-scheduler / ref-not-on-trunk / behind / fresh), and converge
// one drift ISSUE per unhealthy repo in this (sheepdog) repo.
//
// WHY: per-project scheduling made every member maintain itself, and in doing so
// removed the last thing that looked at a member from the OUTSIDE. A member whose
// scheduler was never vendored or has been failing for a fortnight is invisible —
// it is still `covered` to the census, and it files no failure issue because
// nothing runs there to fail. Self-maintenance cannot detect its own absence. The
// census answers "is this repo covered"; this task answers "is that coverage still
// meaning anything".
//
// CLASSIFICATION (per-project-scheduling DESIGN §6, the same note the census and
// RULES.md carry): an ORDINARY PACK TASK, not a fleet mechanism. Its
// *implementation* reads every repo under the owner over a PAT, but its
// declaration, scheduling and lifecycle are exactly those of any pack task — it is
// active because this repo declares the sheepdog pack, and it runs however this
// repo's tasks run. Hence no `session_scope: 'fleet'` and no `fleet` signal: those
// describe how a task is WIRED, and nothing about this task's wiring is
// fleet-shaped. The cross-repo reach lives in the implementation, never in the
// declaration.
//
// Self-contained (imports nothing): the whole contract is this default export.

export default {
  id: 'fleet-freshness',
  frequency: 'weekly',                   // drift is measured in DAYS (staleDays, default 14) — a daily sweep would re-ask a question whose answer cannot have changed
  precondition_signals: [],              // no signal — the sweep reads the fleet itself, over the PAT
  agent_model: 'none',                   // pure code — no agent (agent-preprocessing DESIGN §4)
  expected_outcome: 'none',              // the honest ceiling: the sweep opens DRIFT ISSUES, never a PR — it reports, it does not repair
  agent_instructions: 'task.md',         // vestigial for a none task; the real work is the preprocessing command
  agent_preprocessing: 'node worker.mjs',
  // Three REST reads per member (declaration, scheduler workflow, canon compare)
  // plus the enumeration and the issue convergence, all serial, and a secondary
  // rate limit makes it slower still. Same 900s the census carries, for the same
  // reason: ~10x the expected walk while staying well inside the hourly cadence.
  agent_preprocessing_timeout: 900,
  required_secrets: ['FLEET_GITHUB_TOKEN'], // the account-spanning PAT the sweep reads the fleet with

  // Fire weekly unconditionally. Every input lives OUTSIDE this repo — another
  // member's stamp, another member's workflow, canon's head — and no per-repo
  // collector can see any of them, so there is no signal that would tell us in
  // advance whether the answer changed. The sweep is cheap to no-op: a fleet with
  // nothing behind opens and closes nothing, and an unhealthy member that is still
  // unhealthy for the same reason is not even commented on.
  precondition() {
    return { run: true, reason: 'weekly fleet freshness sweep (the sweep converges drift issues and no-ops cheaply on a fleet that is keeping up)' };
  },
};

// tidy-repo task: tidy-branches — the read-only branch third of the tidy sweep
// (per-project-scheduling DESIGN §6). One weekly full sweep over the repo's open
// branches: which carry genuine unmerged work, which are safe to delete. Recommends;
// never deletes. Worker: task.md. Issues and PRs are separate tasks — one dimension
// per task, each with its own trigger, scope, and tracker, so there is no ordering
// barrier.
//
// WEEKLY, and full every time. The `branches` signal carries NAMES only, so there is
// no windowed subset to narrow to — the whole set is the only scope this dimension
// has. Branch cruft also accumulates on a weekly clock, not a daily one, and the
// verdict is a standing recommendation for a human rather than a same-day alert. So
// the full sweep is a frequency DECLARATION, never a gate trick inside a daily task
// (DESIGN §3).
//
// Self-contained (imports nothing): the whole contract is this default export.

// Branches the tidy review must never assess. Beyond the default branch, the orphan
// `conversation-logs` branch is a grow_with_claudinite artifact (the captured-transcript
// stream, not project work) — it shares no history with main, so single-branch-status
// would flag it "orphaned" for a human on every run. It is infrastructure the tidy
// sweep ignores altogether. Kept as a bare literal, not an import: the pack-independence
// barrier forbids tidy-repo from reaching into grow_with_claudinite, and the name is a
// fixed, well-known one. The stable maintenance branch is likewise never a tidy target —
// it is Claudinite's own standing delivery branch, not project work.
const IGNORED_BRANCHES = new Set(['conversation-logs', 'claudinite/maintenance']);

// A precondition has no repo handle, so it cannot look up the actual default branch
// name to drop it from the candidate set — and the `branches` signal carries every
// open branch, the default included. Presuming the conventional default names here
// keeps a repo whose only branch is its default from firing this task at all, which is
// the whole point of the gate. The worker (task.md) remains the authority that never
// assesses the repo's real default branch, so a repo whose default is unconventionally
// named is still safe — its default just also becomes a (cheap, read-only) candidate.
const PRESUMED_DEFAULT = new Set(['main', 'master']);

export default {
  id: 'tidy-branches',
  frequency: 'weekly',                      // the weekly anchor (DESIGN §2); the full sweep is the declaration
  precondition_signals: ['branches'],       // names only — the assessable set IS the scope
  agent_model: 'sonnet',                    // superseded / orphaned / already-in-main are judgment calls on content
  expected_outcome: 'none',                 // assess-only: never deletes, pushes, or merges; writes only its tracker
  agent_instructions: 'task.md',
  agent_execution_timeout: 600,             // one cheap diff-and-merge-base read per branch

  // The only gate a full sweep needs: is there a branch worth assessing. A repo
  // carrying nothing but its default branch (and the infra branches) stays silent.
  precondition(signals) {
    const branches = (signals.branches?.names ?? [])
      .filter((b) => !IGNORED_BRANCHES.has(b) && !PRESUMED_DEFAULT.has(b));
    if (!branches.length) return { run: false, reason: 'no branches to assess beyond the default and the infra branches' };

    return {
      run: true,
      reason: `weekly full sweep over ${branches.length} branch(es)`,
      context: [`Branches to assess (read-only — recommend deletions, never delete): ${branches.join(', ')}.`],
    };
  },
};

// tidy-repo task: tidy-issues — the ACTING third of the tidy sweep
// (per-project-scheduling DESIGN §6). Triages the issues the window touched, and
// re-checks every open issue when the default branch moved substantively (a real
// commit can implement an old issue without the issue itself being touched).
// Worker: task.md. Branches and PRs are separate tasks: one dimension per task,
// each with its own trigger, scope, and tracker — no ordering barrier between them.
//
// Self-contained (imports nothing): the whole contract is this default export.

export default {
  id: 'tidy-issues',
  frequency: 'daily',                       // the 04:00 slot (DESIGN §2) — the one tidy dimension that ACTS, so latency matters
  precondition_signals: ['issues', 'commits'],
  agent_model: 'sonnet',                    // "implemented in main" is a judgment call against main's current content
  expected_outcome: 'none',                 // writes ISSUES only (the triage actions + its own tracker) — never a PR
  agent_instructions: 'task.md',
  agent_execution_timeout: 900,             // one dimension over a bounded issue list

  // Two triggers, and they are the complete set for this dimension: an issue's
  // triage answer changes when the ISSUE moves, or when `main` moves (which can
  // implement it). So a touched issue is in scope, and a substantive default-branch
  // move widens scope to EVERY open issue — that widening is this task's full sweep,
  // triggered by the thing that changes the answer rather than by the calendar. A
  // housekeeping-only main move (a nightly baseline commit, a bot bump) implements
  // nothing, so it does not widen and a quiet-but-maintained repo isn't re-swept.
  precondition(signals) {
    const substantive = signals.commits?.substantiveChange === true;
    const open = (signals.issues?.open ?? []).map((i) => i.number);
    const touched = signals.issues?.touched ?? [];

    // The scheduler's issues signal already hides the dispatch issues and the
    // standing trackers, so neither can ever be triaged as project work.
    const scope = substantive ? open : touched;
    if (!scope.length) {
      return { run: false, reason: substantive ? 'main moved substantively but the repo has no open issues' : 'no issues touched in the window' };
    }

    return {
      run: true,
      reason: substantive
        ? `main moved substantively — re-check all ${scope.length} open issue(s) against it`
        : 'issues touched in the window',
      context: [`Issues to triage: ${scope.map((n) => `#${n}`).join(', ')}.`],
    };
  },
};

// tidy-repo task: tidy-prs — the read-only PR third of the tidy sweep
// (per-project-scheduling DESIGN §6). One weekly full sweep over every open PR:
// which should stay open, which are closeable. Recommends; never closes. Worker:
// task.md. Issues and branches are separate tasks — one dimension per task, each
// with its own trigger, scope, and tracker, so there is no ordering barrier.
//
// WEEKLY, and full every time: a PR verdict is a standing recommendation for a
// human, not a same-day alert, so re-deriving the whole picture once a week beats
// a daily partial one — and "weekly" is a frequency DECLARATION, never a gate trick
// inside a daily task (DESIGN §3).
//
// Self-contained (imports nothing): the whole contract is this default export.

export default {
  id: 'tidy-prs',
  frequency: 'weekly',                      // the weekly anchor (DESIGN §2); the full sweep is the declaration
  precondition_signals: ['prs'],            // the open set IS the scope — no window narrowing to do
  agent_model: 'sonnet',                    // superseded / already-in-main are judgment calls on the diff
  expected_outcome: 'none',                 // assess-only: never closes, merges, or comments on a PR; writes only its tracker
  agent_instructions: 'task.md',
  agent_execution_timeout: 900,             // a full sweep, but one cheap read-only verdict per PR

  // The only gate a full sweep needs: is there anything open to assess. A repo with
  // no open PRs stays silent.
  precondition(signals) {
    const open = (signals.prs?.open ?? []).map((p) => p.number);
    if (!open.length) return { run: false, reason: 'no open PRs' };

    return {
      run: true,
      reason: `weekly full sweep over ${open.length} open PR(s)`,
      context: [`PRs to assess (read-only — recommend closes, never close): ${open.map((n) => `#${n}`).join(', ')}.`],
    };
  },
};

