1	// Due-slot math for the vendored hourly scheduler (per-project-scheduling
2	// DESIGN §3). Pure and stateless: given the repo's `schedule` anchor, the
3	// frequencies its tasks declare, the current time `now`, and the timestamp
4	// `lastSuccess` of the scheduler's last SUCCESSFUL run (read from the Actions
5	// run ledger GitHub already keeps — there is no watermark file to corrupt),
6	// this decides exactly which frequencies are due and the slot id each is
7	// running under.
8	//
9	// The whole model is: consider ONLY the single most-recent scheduled slot per
10	// frequency, and it is due iff its time falls in `(lastSuccess, now]`.
11	//   - Miss / outage self-heals — the next successful run catches up the one
12	//     most-recent daily/weekly/monthly slot; a 3-day outage yields one catch-up
13	//     evaluation per frequency, never a backfill storm (DESIGN §3.1).
14	//   - HOURLY never catches up for free: its most-recent slot is always the
15	//     current hour, so an outage evaluates the current poll once and never a
16	//     stale one — no special case needed, the most-recent-only rule delivers it.
17	//   - Late / early fire is irrelevant: due-ness is schedule math, never
18	//     wall-clock equality with the (hashed :10–:50) cron minute.
19	//   - First run (`lastSuccess` null / fresh adoption) → every frequency's
20	//     most-recent slot is due: the immediate full evaluation that smoke-tests a
21	//     newly-wired repo (DESIGN §3.1).
22	//
23	// All times are UTC (the `schedule` values are UTC by contract, DESIGN §2). This
24	// module never reads the clock itself — `now` is always injected — so the whole
25	// due-ness decision is deterministic and testable.
26	
27	// The seven legal frequency tokens (DESIGN §1). `task-declaration-shape` is what
28	// rejects anything outside this set at author time; here an unknown token is
29	// simply never due (defensive — the scheduler must not throw on a stray value).
30	export const FREQUENCIES = ['hourly', 'daily-2h', 'daily-1h', 'daily', 'daily+1h', 'weekly', 'monthly'];
31	
32	// The documented anchor defaults (DESIGN §2) — applied when a repo omits
33	// `schedule` or any of its keys. This is the single source of these values; the
34	// checks layer's load-time range validation (engine/checks/helpers/repo-context.mjs)
35	// only bounds them, it does not re-declare them.
36	export const DEFAULT_SCHEDULE = { dailyHour: 4, weeklyDay: 'Sun', monthlyDay: 1 };
37	
38	// Sun-indexed to match Date#getUTCDay (0 = Sunday). Also the canonical weekday
39	// vocabulary the config validator mirrors.
40	export const WEEKDAYS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
41	
42	// Hours the daily family offsets the anchor hour by (DESIGN §2).
43	const DAILY_OFFSETS = { 'daily-2h': -2, 'daily-1h': -1, daily: 0, 'daily+1h': 1 };
44	
45	const HOUR_MS = 3600 * 1000;
46	const DAY_MS = 24 * HOUR_MS;
47	const pad = (n) => String(n).padStart(2, '0');
48	const ymd = (d) => `${d.getUTCFullYear()}-${pad(d.getUTCMonth() + 1)}-${pad(d.getUTCDate())}`;
49	
50	// Last calendar day of a UTC month (day 0 of the next month rolls back).
51	const daysInMonth = (year, monthIndex) => new Date(Date.UTC(year, monthIndex + 1, 0)).getUTCDate();
52	
53	// Fill any absent key with its documented default; leave present values
54	// untouched (the checks layer has already range-validated them at load).
55	export function normalizeSchedule(schedule = {}) {
56	  const s = schedule || {};
57	  return {
58	    dailyHour: Number.isInteger(s.dailyHour) ? s.dailyHour : DEFAULT_SCHEDULE.dailyHour,
59	    weeklyDay: WEEKDAYS.includes(s.weeklyDay) ? s.weeklyDay : DEFAULT_SCHEDULE.weeklyDay,
60	    monthlyDay: Number.isInteger(s.monthlyDay) ? s.monthlyDay : DEFAULT_SCHEDULE.monthlyDay,
61	  };
62	}
63	
64	// The most-recent scheduled slot for one frequency at time `now`:
65	// `{ time: Date, id: string }` where `time` is the slot's UTC instant (≤ now)
66	// and `id` is the dispatch-issue slot id (DESIGN §4). `schedule` is assumed
67	// already normalized. `now` may be a Date or anything the Date ctor accepts.
68	export function mostRecentSlot(frequency, schedule, now) {
69	  const s = normalizeSchedule(schedule);
70	  now = new Date(now);
71	  const nowMs = now.getTime();
72	
73	  if (frequency === 'hourly') {
74	    // The top of the current hour — the poll never backfills a past hour.
75	    const time = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate(), now.getUTCHours()));
76	    return { time, id: `h${ymd(time)}T${pad(time.getUTCHours())}Z` };
77	  }
78	
