124	// The frequencies that are due right now, each with its slot id/time. `lastSuccess`
125	// is the last successful scheduler run's timestamp (Date / ISO string / null);
126	// null means "no prior success" → everything due. Unknown frequency tokens are
127	// ignored (never due) rather than thrown on.
128	export function dueSlots(frequencies, schedule, now, lastSuccess) {
129	  const s = normalizeSchedule(schedule);
130	  now = new Date(now);
131	  const nowMs = now.getTime();
132	  const tMs = lastSuccess === null || lastSuccess === undefined ? null : new Date(lastSuccess).getTime();
133	
134	  const out = [];
135	  for (const frequency of frequencies) {
136	    if (!FREQUENCIES.includes(frequency)) continue;
137	    const slot = mostRecentSlot(frequency, s, now);
138	    const t = slot.time.getTime();
139	    // `t <= nowMs` holds by construction; kept explicit as the stated contract.
140	    const due = tMs === null ? t <= nowMs : t > tMs && t <= nowMs;
141	    if (due) out.push({ frequency, slotId: slot.id, slotTime: slot.time.toISOString() });
142	  }
143	  return out;
144	}
